    /**
 * Kosakata Bahasa Inggris yang diperkaya, khusus untuk halaman /inggris/vocab.
 * Berbeda dari data lintas-bahasa di src/data/curriculum.ts: di sini tiap kata
 * punya contoh kalimat, fakta seru ramah anak, dan tingkat kesulitan.
 */

export type Level = 'pemula' | 'menengah' | 'mahir'

export interface EnWord {
  id: string
  /** Kata dalam Bahasa Inggris */
  word: string
  /** Bantuan pelafalan sederhana untuk anak (huruf latin) */
  say: string
  /** Arti dalam Bahasa Indonesia */
  meaning: string
  emoji: string
  level: Level
  /** Contoh kalimat Bahasa Inggris */
  example: string
  /** Arti contoh kalimat */
  exampleId: string
  /** Satu fakta seru dalam Bahasa Indonesia */
  fact: string
}

export interface EnCategory {
  id: string
  title: string
  emoji: string
  color: string
  color2: string
  words: EnWord[]
}

